<template><view class="page"><PageHead title="青禾有礼"/><view class="content"><view v-if="!state.token" class="card"><view class="bold">登录后查看积分和优惠券</view><view class="subtitle">登录后可签到领积分、兑换和使用优惠券。</view><button class="btn" :loading="busy" :disabled="busy" @click="signIn">立即登录</button></view><view v-if="error" class="error">{{error}}<text v-if="state.token" class="link" @click="load"> 点击重试</text></view><view v-if="loading" class="subtitle">加载中…</view><template v-if="state.token"><view class="benefit-hero"><view class="section-kicker">A GIFT FOR YOUR EVERYDAY</view><view class="title">每一份热爱，都有回馈</view><view class="subtitle">我的积分 <text class="points">{{me.points||0}}</text></view><view class="between" style="margin-top:30rpx"><button class="btn light" :disabled="busy||loading||!me.id||me.checkedIn" @click="checkin">{{me.checkedIn?'今日已签到':'签到领10积分'}}</button><button class="btn" :disabled="busy||loading||!me.id" @click="redeem">100积分兑¥5券</button></view></view><view class="section-head title">我的优惠券</view><view v-for="c in coupons" :key="c.id" class="coupon"><view class="coupon-amount"><text>¥</text>{{money(c.amount)}}<view class="tiny">满{{money(c.minimum)}}元可用</view></view><view><view class="bold">{{c.title}}</view><view class="subtitle small">有效至 {{String(c.expires_at).slice(0,10)}}</view><view class="tiny muted" style="margin-top:10rpx">全平台商家通用 · 每单限用一张</view></view></view><view v-if="!loading&&!error&&!coupons.length" class="empty">暂无可用优惠券，签到攒积分试试吧</view><view class="card small muted" style="line-height:1.9">每天签到可领取10积分；完成订单按实付整元累计积分。100积分可兑换一张满20减5优惠券，有效期14天。</view></template></view></view></template>
<script setup>
import {ref} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import PageHead from '../../components/PageHead.vue'
import {state,money,toast,confirm} from '../../lib/api'
import {useMemberPage} from '../../lib/member-page'
const me=ref({}),coupons=ref([])
const {loading,busy,error,load,signIn,run}=useMemberPage(
 request=>Promise.all([request('/me'),request('/coupons')]),
 data=>{[me.value,coupons.value]=data},()=>{me.value={};coupons.value=[]})
async function checkin(){if(loading.value||!me.value.id||me.value.checkedIn)return;await run(async session=>{await session.request('/checkin','POST');session.assertCurrent();toast('签到成功 +10积分');await load()})}
async function redeem(){if(loading.value||!me.value.id)return;await run(async session=>{if(!await confirm('使用100积分兑换满20减5优惠券？'))return;await session.request('/redeem','POST');session.assertCurrent();toast('兑换成功');await load()})}
onShow(load)
</script><style scoped>.benefit-hero{padding:33rpx 25rpx;border-radius:28rpx;background:linear-gradient(130deg,#e7ecd5,#f2edda)}.benefit-hero .title{font-size:34rpx;margin-top:20rpx}.points{font-size:48rpx;color:#6c845b;margin-left:15rpx;font-weight:700}.benefit-hero button{font-size:23rpx;padding:22rpx}.coupon{display:flex;align-items:center;gap:30rpx;background:#fff;border:1rpx solid #eceee1;border-radius:22rpx;margin-bottom:23rpx;padding:30rpx 24rpx}.coupon-amount{font-size:63rpx;color:#b39a53;text-align:center;border-right:2rpx dashed #e7e7d9;padding-right:28rpx;min-width:170rpx;font-weight:700}.coupon-amount>text{font-size:27rpx}.coupon-amount .tiny{font-weight:400}</style>
